select 
from wm_barcode

    del_flag = '0'
    and barcode_type = #{barcodeType}
    and barcode_format = #{barcodeFormat}
    and biz_id = #{bizId}

        and barcode_content like concat('%', #{contentKeyword}, '%')

    and enable_flag = #{enableFlag}

order by barcode_id desc

select count(*) from wm_barcode
where barcode_content = #{barcodeContent} and del_flag = '0'
and barcode_id != #{excludeId}

mapper.update:
update wm_barcode
set barcode_url = #{barcodeUrl}
where barcode_id = #{barcodeId} and del_flag = '0'

update wm_barcode
set del_flag = '1', enable_flag = 'N'
where barcode_id = #{barcodeId}
